(() => {
  const clean = (s) => (s || '').replace(/\u00a0/g, ' ').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  const blk = document.getElementById('education');
  if (!blk) return 'NO BLOCK';
  return {
    text: clean(blk.innerText).slice(0, 500),
    btns: [...blk.querySelectorAll('span,a,button,div[class*=btn]')].filter(vis).map(b => clean(b.innerText)).filter(t => t && t.length < 14).slice(0, 30),
    kas: [...blk.querySelectorAll('[ka]')].map(e => e.getAttribute('ka') + '|' + clean(e.innerText).slice(0,10) + '|w=' + Math.round(e.getBoundingClientRect().width)).slice(0, 30),
    fields: [...blk.querySelectorAll('input,textarea,[contenteditable=true]')].map((e,i)=>({i, vis: vis(e), ph: (e.placeholder||'').slice(0,30), val: clean(e.value||e.innerText).slice(0,40)})).slice(0,20)
  };
})()
